"383 :     private void removeDeclaration(Reference declaration) {
384 :       Node varNode = declaration.getParent();
385 :       varNode.removeChild(declaration.getNameNode());
386 : 
387 :       // Remove var node if empty
388 :       if (!varNode.hasChildren()) {
389 :         Preconditions.checkState(varNode.getType() == Token.VAR);
390 : 
391 :         Node grandparent = declaration.getGrandparent();
392 :         NodeUtil.removeChild(grandparent, varNode);
393 :       }
394 : 
395 :       compiler.reportCodeChange();
396 :     }"

